    function __ESBMC_assume(bool) internal pure {}
    function run(uint _am, uint minSum) public {
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore < minSum || balBefore < _am);
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
