contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _am, uint256 minSum) internal {
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(balBefore < minSum || balBefore < _am);
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }

    function testFuzz_run(uint256 _am, uint256 minSum) public {
        _run(_am, minSum);
    }

    receive() external payable {}
